def key(u):return unquote(u or '').split('#',1)[0].replace(' ','_').casefold().rstrip('/')
p=Path('data/wookieepedia-comic-appearance-indices.jsonl');b=p.read_bytes()
if hashlib.sha256(b).hexdigest()!=INDEX_SHA:raise ValueError('appearance index changed')
issue_map={}
for line in b.decode().splitlines():
 r=json.loads(line)
 for a in r['appearances']:issue_map.setdefault(key(a['target_url']),set()).add(r['work_id'])
rows=[]
for i in range(2):
 file=hf_hub_download(REPO,f'pretrain/wookieepedia-{i:05d}-of-00002.parquet',repo_type='dataset',revision=REV)
 for batch in pq.ParquetFile(file).iter_batches(batch_size=2048):
  for x in batch.to_pylist():
   if x['doc_id'] not in PINS:continue
   text=x['text'] or '';digest=hashlib.sha256(text.encode()).hexdigest();issues=sorted(issue_map.get(key(x['url']),[]))
   if digest!=PINS[x['doc_id']] or x['continuity']!='legends' or not text or not issues or re.search(r'["“”]|(?m:^\s*>)',text) or requires_review(text):raise ValueError('source or screen changed: '+x['doc_id'])
   x.update(sha256=digest,upstream_repository=REPO,upstream_revision=REV,evidence_class='secondary',license='CC BY-SA 3.0 (wiki contributor text; third-party material may have separate terms)',attribution='Wookieepedia contributors; see linked article history',appearance_issue_ids=issues,appearance_index_sha256=INDEX_SHA,coverage='Linked by editorial issue appearance lists; not proof of complete or accurate issue contents or rights clearance.',embedded=False);rows.append(x)
if len(rows)!=len(PINS) or len({r['doc_id'] for r in rows})!=len(PINS):raise ValueError('missing or duplicate records')
rows.sort(key=lambda x:x['doc_id']);output=''.join(json.dumps(x,ensure_ascii=False,sort_keys=True)+'\n' for x in rows)
if hashlib.sha256(output.encode()).hexdigest()!='37819f80f00023384d78a8f2c0bd81398b579d7e55ac5bd2b80fc994af8d42b3':raise ValueError('Output changed; re-screen before release')
Path('data/wookieepedia-comic-linked-legends.jsonl').write_text(output);print('selected',len(rows),'unembedded linked records')
